//! Emits Rust source from a resolved [`Model`].
//!
//! Generated files depend on `compact_encoding` and `bytes` only. Every struct
//! carries the schema's latest version in its `Codec` impl and the exact
//! version in `encode_version`/`decode_version`, which is what the JS
//! `setVersion` global does at runtime.

use std::collections::BTreeMap;
use std::fmt::Write;

use super::error::{Error, Result};
use super::model::{Field, FlagKind, Kind, Model, Prim, Ty};

/// Codegen knobs. `hyperschema`'s own `external` types are supplied by the
/// consumer, so their Rust type has to come from here.
#[derive(Debug, Clone, Default)]
pub struct Options {
    /// `external` name in the schema to Rust type path, emitted verbatim.
    pub externals: BTreeMap<String, String>,
}

impl Options {
    pub fn new() -> Self {
        Self::default()
    }

    /// Registers the Rust path that stands in for a schema `external` type.
    pub fn external(mut self, name: impl Into<String>, path: impl Into<String>) -> Self {
        self.externals.insert(name.into(), path.into());
        self
    }
}

const IND: &str = "    ";

#[derive(Clone, Copy, PartialEq, Eq)]
enum K {
    Struct,
    Enum,
    Array,
    Record,
    Alias,
    Versioned,
    External,
}

pub fn generate(model: &Model, opts: &Options) -> Result<String> {
    let mut externals: BTreeMap<usize, String> = BTreeMap::new();
    for (i, t) in model.types.iter().enumerate() {
        if let Kind::External(e) = &t.kind {
            if !used(model, i) {
                continue;
            }
            let path = opts.externals.get(&e.external).ok_or_else(|| {
                Error::Schema(format!(
                    "`{}` needs a Rust path for external type `{}`; pass it with Options::external",
                    t.fqn, e.external
                ))
            })?;
            externals.insert(i, path.clone());
        }
    }

    let mut e = Emitter {
        m: model,
        externals,
        out: String::with_capacity(16 * 1024),
    };
    e.run()?;
    Ok(e.out)
}

/// An external is only a problem when something actually refers to it.
fn used(model: &Model, idx: usize) -> bool {
    for t in &model.types {
        match &t.kind {
            Kind::Struct(s) => {
                if s.fields.iter().any(|f| refers(&f.ty, idx)) {
                    return true;
                }
            }
            Kind::Array(a) => {
                if refers(&a.elem, idx) {
                    return true;
                }
            }
            Kind::Record(r) => {
                if refers(&r.key, idx) || refers(&r.value, idx) {
                    return true;
                }
            }
            Kind::Alias(a) => {
                if refers(&a.target, idx) {
                    return true;
                }
            }
            Kind::Versioned(v) => {
                if v.defs.iter().any(|d| refers(&d.ty, idx)) {
                    return true;
                }
            }
            Kind::Enum(_) | Kind::External(_) => {}
        }
    }
    false
}

fn refers(ty: &Ty, idx: usize) -> bool {
    matches!(ty, Ty::External(i) if *i == idx)
}

/// `&self.x` becomes `self.x`, `v` becomes `*v`.
fn value(expr: &str) -> String {
    match expr.strip_prefix('&') {
        Some(rest) => rest.to_string(),
        None => format!("*{expr}"),
    }
}

/// `&self.x` and `v` both reach methods without parentheses, since `.` binds
/// tighter than `&`.
fn at(expr: &str) -> &str {
    expr.strip_prefix('&').unwrap_or(expr)
}

struct Emitter<'a> {
    m: &'a Model,
    externals: BTreeMap<usize, String>,
    out: String,
}

impl Emitter<'_> {
    fn run(&mut self) -> Result<()> {
        let _ = writeln!(
            self.out,
            "// Generated by hyperschema-rs. Do not edit.\n\
             // Schema version: {}.\n",
            self.m.version
        );
        let _ = writeln!(self.out, "pub const VERSION: u64 = {};\n", self.m.version);

        for ns in 0..self.m.namespaces.len() {
            let module = self.m.namespaces[ns].module.clone();
            let _ = writeln!(
                self.out,
                "/// Types of schema namespace `{}`.\n\
                 #[allow(dead_code, unused_imports, unused_variables, clippy::all)]\n\
                 pub mod {module} {{",
                self.m.namespaces[ns].name
            );
            self.imports();
            self.out.push('\n');

            for i in 0..self.m.types.len() {
                if self.m.types[i].ns != ns {
                    continue;
                }
                match self.kind_of(i) {
                    K::Struct => self.struct_def(i)?,
                    K::Enum => self.enum_def(i),
                    K::Array => self.array_def(i)?,
                    K::Record => self.record_def(i),
                    K::Alias => self.alias_def(i),
                    K::Versioned => self.versioned_def(i),
                    K::External => {
                        let fqn = self.m.types[i].fqn.clone();
                        match self.externals.get(&i) {
                            Some(path) => {
                                self.line(1, &format!("// `{fqn}` is external: `{path}`."))
                            }
                            None => {
                                self.line(1, &format!("// `{fqn}` is external and unreferenced."))
                            }
                        }
                        self.line(1, "");
                    }
                }
            }

            self.out.push_str("}\n\n");
        }

        Ok(())
    }

    fn kind_of(&self, idx: usize) -> K {
        match &self.m.types[idx].kind {
            Kind::Struct(_) => K::Struct,
            Kind::Enum(_) => K::Enum,
            Kind::Array(_) => K::Array,
            Kind::Record(_) => K::Record,
            Kind::Alias(_) => K::Alias,
            Kind::Versioned(_) => K::Versioned,
            Kind::External(_) => K::External,
        }
    }

    fn imports(&mut self) {
        let _ = writeln!(
            self.out,
            "{IND}use bytes::Bytes;\n\
             {IND}use compact_encoding::{{\n\
             {IND}{IND}Codec, Error, MAX_ARRAY_DECODE, Reader as CReader, Result, Writer as CWriter,\n\
             {IND}{IND}buffer_len, int_len, optional_buffer_len, uint_len,\n\
             {IND}}};\n\
             {IND}use std::net::{{\n\
             {IND}{IND}IpAddr, Ipv4Addr, Ipv6Addr, SocketAddr, SocketAddrV4, SocketAddrV6,\n\
             {IND}}};\n\
             {IND}use super::VERSION;"
        );
    }

    fn line(&mut self, indent: usize, text: &str) {
        for _ in 0..indent {
            self.out.push_str(IND);
        }
        self.out.push_str(text);
        self.out.push('\n');
    }

    fn path(&self, idx: usize, cur_ns: usize) -> String {
        if let Some(path) = self.externals.get(&idx) {
            return path.clone();
        }
        let t = &self.m.types[idx];
        if t.ns == cur_ns {
            t.rust_name.clone()
        } else {
            format!("super::{}::{}", self.m.namespaces[t.ns].module, t.rust_name)
        }
    }

    fn ty_str(&self, ty: &Ty, cur_ns: usize) -> String {
        match ty {
            Ty::Prim(p) => prim_type(*p).to_string(),
            Ty::Struct(i) | Ty::Enum(i) | Ty::Versioned(i) | Ty::External(i) => {
                self.path(*i, cur_ns)
            }
            Ty::Array(i) => {
                let a = self.m.as_array(*i);
                if a.newtype {
                    self.path(*i, cur_ns)
                } else {
                    format!("Vec<{}>", self.ty_str(&a.elem, cur_ns))
                }
            }
            Ty::Record(i) => self.path(*i, cur_ns),
        }
    }

    // -- structs ------------------------------------------------------------

    fn field_type(&self, f: &Field, cur_ns: usize) -> String {
        let base = if f.array {
            format!("Vec<{}>", self.ty_str(&f.ty, cur_ns))
        } else if f.boxed {
            format!("Box<{}>", self.ty_str(&f.ty, cur_ns))
        } else {
            self.ty_str(&f.ty, cur_ns)
        };
        if f.constant.as_ref().is_some_and(|c| c.is_null()) {
            return format!("Option<{base}>");
        }
        if f.is_flag_field() || f.constant.is_some() {
            return base;
        }
        if !f.required && !self.m.option_flavored(&f.ty) {
            return format!("Option<{base}>");
        }
        base
    }

    fn struct_def(&mut self, idx: usize) -> Result<()> {
        let cur = self.m.types[idx].ns;
        let fqn = self.m.types[idx].fqn.clone();
        let name = self.m.types[idx].rust_name.clone();
        let s = self.m.as_struct(idx);
        let inlined = s.inlined;

        let fields: Vec<(String, String)> = s
            .fields
            .iter()
            .map(|f| (f.rust_name.clone(), self.field_type(f, cur)))
            .collect();

        self.line(1, &format!("/// `{fqn}`"));
        self.line(1, "#[derive(Debug, Clone, PartialEq)]");
        self.line(1, &format!("pub struct {name} {{"));
        for (field, ty) in &fields {
            self.line(2, &format!("pub {field}: {ty},"));
        }
        self.line(1, "}");
        self.line(1, "");
        self.line(1, &format!("impl {name} {{"));

        self.flags_version(idx);
        self.encoded_len_version(idx);
        self.encode_version(idx);
        self.decode_version(idx);
        if inlined {
            self.inline_helpers(idx);
        }

        self.line(1, "}");
        self.line(1, "");
        self.line(1, &format!("impl Codec for {name} {{"));
        self.line(2, "fn encoded_len(&self) -> usize {");
        self.line(3, "self.encoded_len_version(VERSION)");
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn encode(&self, w: &mut CWriter) {");
        self.line(3, "self.encode_version(VERSION, w);");
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn decode(r: &mut CReader) -> Result<Self> {");
        self.line(3, "Self::decode_version(r, VERSION)");
        self.line(2, "}");
        self.line(1, "}");
        self.line(1, "");
        Ok(())
    }

    fn flags_version(&mut self, idx: usize) {
        let s = self.m.as_struct(idx);
        if s.flags_bits == 0 {
            return;
        }
        let fields = s.fields.clone();
        self.line(
            2,
            "/// The flags word this struct writes at its flags position.",
        );
        self.line(2, "pub fn flags_version(&self, version: u64) -> u64 {");
        self.line(3, "let mut flags = 0u64;");
        for f in &fields {
            if f.constant.is_some() {
                continue;
            }
            // Required fields are always on the wire; only optional ones are gated.
            let gate = !f.required && f.version > 1;
            let mut ind = 3;
            if gate {
                self.line(ind, &format!("if version >= {} {{", f.version));
                ind += 1;
            }
            match f.flag_kind {
                FlagKind::Bool => self.line(
                    ind,
                    &format!(
                        "if self.{} {{ flags |= 1u64 << {}; }}",
                        f.rust_name, f.flag_bit
                    ),
                ),
                FlagKind::Bitwise(n) => {
                    let mask = (1u64 << n) - 1;
                    let value = if f.flag_bit == 0 {
                        format!("(self.{} as u64) & {mask}", f.rust_name)
                    } else {
                        format!("((self.{} as u64) & {mask}) << {}", f.rust_name, f.flag_bit)
                    };
                    self.line(ind, &format!("flags |= {value};"));
                }
                FlagKind::None if f.inline => {
                    let shift = if f.child_offset == 0 {
                        String::new()
                    } else {
                        format!(" << {}", f.child_offset)
                    };
                    if f.required {
                        self.line(
                            ind,
                            &format!(
                                "flags |= self.{}.flags_version(version){shift};",
                                f.rust_name
                            ),
                        );
                    } else {
                        self.line(ind, &format!("if let Some(v) = &self.{} {{", f.rust_name));
                        self.line(ind + 1, &format!("flags |= 1u64 << {};", f.flag_bit));
                        self.line(
                            ind + 1,
                            &format!("flags |= v.flags_version(version){shift};"),
                        );
                        self.line(ind, "}");
                    }
                }
                FlagKind::None if !f.required => {
                    self.line(ind, &format!("if self.{}.is_some() {{", f.rust_name));
                    self.line(ind + 1, &format!("flags |= 1u64 << {};", f.flag_bit));
                    self.line(ind, "}");
                }
                FlagKind::None => {}
            }
            if gate {
                self.line(3, "}");
            }
        }
        self.line(3, "flags");
        self.line(2, "}");
        self.line(2, "");
    }

    fn encoded_len_version(&mut self, idx: usize) {
        let s = self.m.as_struct(idx);
        let cur = self.m.types[idx].ns;
        let fields = s.fields.clone();
        let flags_bits = s.flags_bits;
        let compact = s.compact;

        self.line(
            2,
            "/// Number of bytes `encode_version` writes for this value.",
        );
        self.line(
            2,
            "pub fn encoded_len_version(&self, version: u64) -> usize {",
        );
        self.line(3, "let mut n = 0usize;");
        if flags_bits > 0 {
            if compact {
                self.line(3, &format!("n += {};", flag_width(flags_bits)));
            } else {
                self.line(3, "let flags = self.flags_version(version);");
                self.line(3, "n += uint_len(flags);");
            }
        }
        for f in &fields {
            if f.constant.is_some() || f.is_flag_field() {
                continue;
            }
            // Required fields are always on the wire; only optional ones are gated.
            let gate = !f.required && f.version > 1;
            let mut ind = 3;
            if gate {
                self.line(ind, &format!("if version >= {} {{", f.version));
                ind += 1;
            }
            if f.required {
                let len = if f.inline {
                    format!("self.{}.encoded_len_inline(version)", f.rust_name)
                } else {
                    self.len_field(f, cur, &format!("&self.{}", f.rust_name))
                };
                self.line(ind, &format!("n += {len};"));
            } else if !f.array && self.m.option_flavored(&f.ty) {
                self.line(ind, &format!("if self.{}.is_some() {{", f.rust_name));
                let len = self.len_field(f, cur, &format!("&self.{}", f.rust_name));
                self.line(ind + 1, &format!("n += {len};"));
                self.line(ind, "}");
            } else {
                self.line(ind, &format!("if let Some(v) = &self.{} {{", f.rust_name));
                let len = if f.inline {
                    "v.encoded_len_inline(version)".to_string()
                } else {
                    self.len_field(f, cur, "v")
                };
                self.line(ind + 1, &format!("n += {len};"));
                self.line(ind, "}");
            }
            if gate {
                self.line(3, "}");
            }
        }
        self.line(3, "n");
        self.line(2, "}");
        self.line(2, "");
    }

    fn encode_version(&mut self, idx: usize) {
        let s = self.m.as_struct(idx);
        let cur = self.m.types[idx].ns;
        let fields = s.fields.clone();
        let flags_bits = s.flags_bits;
        let flags_position = s.flags_position;
        let compact = s.compact;

        self.line(
            2,
            "/// Writes the value as the schema encoded it at `version`.",
        );
        self.line(
            2,
            "pub fn encode_version(&self, version: u64, w: &mut CWriter) {",
        );
        if flags_bits > 0 {
            self.line(3, "let flags = self.flags_version(version);");
        }
        self.field_bodies(cur, &fields, 3, flags_position, flags_bits, compact, true);
        self.line(2, "}");
        self.line(2, "");
    }

    /// Field encoding statements shared by `encode_version` and `encode_inline`.
    #[allow(clippy::too_many_arguments)]
    fn field_bodies(
        &mut self,
        cur: usize,
        fields: &[Field],
        indent: usize,
        flags_position: i64,
        flags_bits: u32,
        compact: bool,
        with_flags: bool,
    ) {
        for (i, f) in fields.iter().enumerate() {
            if with_flags && i as i64 == flags_position {
                self.write_flags(indent, flags_bits, compact);
            }
            if f.constant.is_some() || f.is_flag_field() {
                continue;
            }
            // Required fields are always on the wire; only optional ones are gated.
            let gate = !f.required && f.version > 1;
            let mut ind = indent;
            if gate {
                self.line(ind, &format!("if version >= {} {{", f.version));
                ind += 1;
            }
            if f.required {
                if f.inline {
                    self.line(
                        ind,
                        &format!("self.{}.encode_inline(version, w);", f.rust_name),
                    );
                } else {
                    self.encode_field(f, cur, &format!("&self.{}", f.rust_name), ind);
                }
            } else if !f.array && self.m.option_flavored(&f.ty) {
                self.line(ind, &format!("if self.{}.is_some() {{", f.rust_name));
                self.encode_field(f, cur, &format!("&self.{}", f.rust_name), ind + 1);
                self.line(ind, "}");
            } else {
                self.line(ind, &format!("if let Some(v) = &self.{} {{", f.rust_name));
                if f.inline {
                    self.line(ind + 1, "v.encode_inline(version, w);");
                } else {
                    self.encode_field(f, cur, "v", ind + 1);
                }
                self.line(ind, "}");
            }
            if gate {
                self.line(indent, "}");
            }
        }
    }

    fn write_flags(&mut self, ind: usize, bits: u32, compact: bool) {
        if bits == 0 {
            return;
        }
        let text = if compact {
            match flag_width(bits) {
                1 => "w.uint8(flags as u8);",
                2 => "w.uint16(flags as u16);",
                3 => "w.uint24(flags as u32);",
                4 => "w.uint32(flags as u32);",
                5 => "w.uint40(flags);",
                6 => "w.uint48(flags);",
                7 => "w.uint56(flags);",
                _ => "w.uint64(flags);",
            }
        } else {
            "w.uint(flags);"
        };
        self.line(ind, text);
    }

    fn decode_version(&mut self, idx: usize) {
        let s = self.m.as_struct(idx);
        let cur = self.m.types[idx].ns;
        let fields = s.fields.clone();
        let flags_bits = s.flags_bits;
        let flags_position = s.flags_position;
        let compact = s.compact;
        let always_optional = s.always_optional;

        self.line(2, "/// Reads a value the schema encoded at `version`.");
        self.line(
            2,
            "pub fn decode_version(r: &mut CReader, version: u64) -> Result<Self> {",
        );

        let mut pre: Vec<usize> = Vec::new();
        for (i, f) in fields.iter().enumerate() {
            if i as i64 == flags_position {
                break;
            }
            pre.push(i);
            if f.constant.is_none() {
                let expr = self.decode_field_value(f, cur);
                self.line(3, &format!("let v{i} = {expr};"));
            }
        }
        if flags_bits > 0 {
            let read = if compact {
                match flag_width(flags_bits) {
                    1 => "r.uint8()? as u64",
                    2 => "r.uint16()? as u64",
                    3 => "r.uint24()? as u64",
                    4 => "r.uint32()? as u64",
                    5 => "r.uint40()?",
                    6 => "r.uint48()?",
                    7 => "r.uint56()?",
                    _ => "r.uint64()?",
                }
            } else {
                "r.uint()?"
            };
            let read = if always_optional {
                format!("let flags = {read};")
            } else {
                format!("let flags = if r.remaining() > 0 {{ {read} }} else {{ 0 }};")
            };
            if !pre.is_empty() {
                self.line(3, "");
            }
            self.line(3, &read);
        }
        if flags_bits > 0 || !pre.is_empty() {
            self.line(3, "");
        }

        self.line(3, "Ok(Self {");
        for (i, f) in fields.iter().enumerate() {
            let expr = if pre.contains(&i) && f.constant.is_none() {
                format!("v{i}")
            } else {
                self.decode_field(f, cur)
            };
            self.line(4, &format!("{}: {expr},", f.rust_name));
        }
        self.line(3, "})");
        self.line(2, "}");
        self.line(2, "");
    }

    fn decode_field(&self, f: &Field, cur_ns: usize) -> String {
        if let Some(c) = &f.constant {
            return constant_literal(c);
        }
        if f.is_flag_field() {
            let expr = match f.flag_kind {
                FlagKind::Bool => format!("flags & (1u64 << {}) != 0", f.flag_bit),
                FlagKind::Bitwise(n) => {
                    let mask = (1u64 << n) - 1;
                    if f.flag_bit == 0 {
                        format!("(flags as u8) & {mask}")
                    } else {
                        format!("((flags >> {}) as u8) & {mask}", f.flag_bit)
                    }
                }
                FlagKind::None => unreachable!(),
            };
            return if f.version > 1 {
                format!("if version >= {} {{ {expr} }} else {{ 0 }}", f.version)
            } else {
                expr
            };
        }

        let value = if f.inline {
            let child = f.child.expect("validated inline target");
            let child_name = self.path(child, cur_ns);
            let offset = f.child_offset;
            format!("{child_name}::decode_inline(r, version, flags >> {offset})?")
        } else {
            let value = self.decode_field_value(f, cur_ns);
            if f.boxed {
                format!("Box::new({value})")
            } else {
                value
            }
        };

        if f.required {
            return value;
        }

        let condition = if f.version > 1 {
            format!(
                "version >= {} && flags & (1u64 << {}) != 0",
                f.version, f.flag_bit
            )
        } else {
            format!("flags & (1u64 << {}) != 0", f.flag_bit)
        };
        if self.m.option_flavored(&f.ty) && !f.array {
            format!("if {condition} {{ {value} }} else {{ None }}")
        } else {
            format!("if {condition} {{ Some({value}) }} else {{ None }}")
        }
    }

    fn inline_helpers(&mut self, idx: usize) {
        let s = self.m.as_struct(idx);
        let cur = self.m.types[idx].ns;
        let fields = s.fields.clone();
        let flags_position = s.flags_position;
        let flags_bits = s.flags_bits;
        let compact = s.compact;

        self.line(
            2,
            "/// Bytes this value contributes where a parent inlines it.",
        );
        self.line(
            2,
            "pub fn encoded_len_inline(&self, version: u64) -> usize {",
        );
        self.line(3, "let mut n = 0usize;");
        for f in &fields {
            if f.constant.is_some() || f.is_flag_field() {
                continue;
            }
            // Required fields are always on the wire; only optional ones are gated.
            let gate = !f.required && f.version > 1;
            let mut ind = 3;
            if gate {
                self.line(ind, &format!("if version >= {} {{", f.version));
                ind += 1;
            }
            if f.required {
                let len = if f.inline {
                    format!("self.{}.encoded_len_inline(version)", f.rust_name)
                } else {
                    self.len_field(f, cur, &format!("&self.{}", f.rust_name))
                };
                self.line(ind, &format!("n += {len};"));
            } else {
                self.line(ind, &format!("if let Some(v) = &self.{} {{", f.rust_name));
                let len = if f.inline {
                    "v.encoded_len_inline(version)".to_string()
                } else {
                    self.len_field(f, cur, "v")
                };
                self.line(ind + 1, &format!("n += {len};"));
                self.line(ind, "}");
            }
            if gate {
                self.line(3, "}");
            }
        }
        self.line(3, "n");
        self.line(2, "}");
        self.line(2, "");

        self.line(
            2,
            "/// Writes the fields without a flags word; a parent owns it.",
        );
        self.line(
            2,
            "pub fn encode_inline(&self, version: u64, w: &mut CWriter) {",
        );
        if fields
            .iter()
            .all(|f| f.constant.is_some() || f.is_flag_field())
        {
            self.line(3, "let _ = (version, w);");
        }
        self.field_bodies(cur, &fields, 3, flags_position, flags_bits, compact, false);
        self.line(2, "}");
        self.line(2, "");

        self.line(
            2,
            "/// Reads the fields from a parent's flags word, shifted to this struct.",
        );
        self.line(
            2,
            "pub fn decode_inline(r: &mut CReader, version: u64, flags: u64) -> Result<Self> {",
        );
        if fields.is_empty() {
            self.line(3, "let _ = (r, version, flags);");
        }
        self.line(3, "Ok(Self {");
        for f in &fields {
            let expr = self.decode_field(f, cur);
            self.line(4, &format!("{}: {expr},", f.rust_name));
        }
        self.line(3, "})");
        self.line(2, "}");
        self.line(2, "");
    }

    // -- field value emission ----------------------------------------------

    fn encode_field(&mut self, f: &Field, cur: usize, expr: &str, ind: usize) {
        if f.array {
            self.encode_items(&f.ty, cur, expr, ind);
        } else {
            let framed = self.m.frameable(&f.ty);
            self.encode_ty(&f.ty, cur, expr, ind, framed);
        }
    }

    fn len_field(&self, f: &Field, cur: usize, expr: &str) -> String {
        if f.array {
            self.len_items(&f.ty, cur, expr)
        } else {
            let framed = self.m.frameable(&f.ty);
            self.len_ty(&f.ty, cur, expr, framed)
        }
    }

    fn decode_field_value(&self, f: &Field, cur: usize) -> String {
        if f.array {
            self.decode_items(&f.ty, cur)
        } else {
            let framed = self.m.frameable(&f.ty);
            self.decode_ty(&f.ty, cur, framed)
        }
    }

    /// A `c.array(...)` body: a count and then each element.
    fn encode_items(&mut self, elem: &Ty, cur: usize, head: &str, ind: usize) {
        if is_bool_ty(elem) {
            // `head` is already a reference to the `Vec<bool>`.
            self.line(ind, &format!("w.bitarray({head});"));
        } else {
            let head = at(head);
            self.line(ind, &format!("w.uint({head}.len() as u64);"));
            self.line(ind, &format!("for item in {head}.iter() {{"));
            self.encode_ty(elem, cur, "item", ind + 1, self.m.frameable(elem));
            self.line(ind, "}");
        }
    }

    fn len_items(&self, elem: &Ty, cur: usize, head: &str) -> String {
        let head = at(head);
        if is_bool_ty(elem) {
            format!("uint_len({head}.len() as u64) + {head}.len().div_ceil(8)")
        } else {
            let item = self.len_ty(elem, cur, "item", self.m.frameable(elem));
            format!(
                "uint_len({head}.len() as u64) + {head}.iter().map(|item| {item}).sum::<usize>()"
            )
        }
    }

    fn decode_items(&self, elem: &Ty, cur: usize) -> String {
        if is_bool_ty(elem) {
            return "r.bitarray()?".to_string();
        }
        let item = self.decode_ty(elem, cur, self.m.frameable(elem));
        format!(
            "{{ let n = r.uint()?; \
             if n > MAX_ARRAY_DECODE {{ return Err(Error::ArrayTooBig(n)); }} \
             let mut items = Vec::with_capacity((n as usize).min(r.remaining())); \
             for _ in 0..n {{ items.push({item}); }} \
             items }}"
        )
    }

    fn encode_ty(&mut self, ty: &Ty, cur: usize, expr: &str, ind: usize, framed: bool) {
        if framed {
            let len = self.len_ty(ty, cur, expr, false);
            self.line(ind, "{");
            self.line(ind + 1, &format!("let n = {len};"));
            self.line(ind + 1, "w.uint(n as u64);");
            self.encode_ty(ty, cur, expr, ind + 1, false);
            self.line(ind, "}");
            return;
        }

        match ty {
            Ty::Prim(p) => {
                if let Some(text) = prim_encode(*p, expr) {
                    let mut lines = text.lines();
                    if let Some(first) = lines.next() {
                        self.line(ind, first);
                    }
                    for rest in lines {
                        self.line(ind, rest);
                    }
                }
            }
            Ty::Struct(_) | Ty::Versioned(_) => {
                self.line(ind, &format!("{}.encode_version(version, w);", at(expr)));
            }
            Ty::Enum(_) => self.line(ind, &format!("w.uint({}.value());", at(expr))),
            Ty::External(_) => self.line(ind, &format!("Codec::encode({expr}, w);")),
            Ty::Array(i) => {
                let a = self.m.as_array(*i);
                let head = if a.newtype {
                    format!("&{}.0", at(expr))
                } else {
                    expr.to_string()
                };
                self.encode_items(&a.elem, cur, &head, ind);
            }
            Ty::Record(i) => {
                let r = self.m.as_record(*i);
                let head = format!("{}.0", at(expr));
                self.line(ind, &format!("w.uint({head}.len() as u64);"));
                self.line(ind, &format!("for (k, v) in {head}.iter() {{"));
                self.encode_ty(&r.key, cur, "k", ind + 1, false);
                self.encode_ty(&r.value, cur, "v", ind + 1, false);
                self.line(ind, "}");
            }
        }
    }

    fn len_ty(&self, ty: &Ty, cur: usize, expr: &str, framed: bool) -> String {
        let inner = match ty {
            Ty::Prim(p) => prim_len(*p, expr),
            Ty::Struct(_) | Ty::Versioned(_) => {
                format!("{}.encoded_len_version(version)", at(expr))
            }
            Ty::Enum(_) => format!("uint_len({}.value())", at(expr)),
            Ty::External(_) => format!("Codec::encoded_len({expr})"),
            Ty::Array(i) => {
                let a = self.m.as_array(*i);
                let head = if a.newtype {
                    format!("&{}.0", at(expr))
                } else {
                    expr.to_string()
                };
                self.len_items(&a.elem, cur, &head)
            }
            Ty::Record(i) => {
                let r = self.m.as_record(*i);
                let key = self.len_ty(&r.key, cur, "k", false);
                let value = self.len_ty(&r.value, cur, "v", false);
                let head = format!("{}.0", at(expr));
                format!(
                    "uint_len({head}.len() as u64) + {head}.iter().map(|(k, v)| {key} + {value}).sum::<usize>()"
                )
            }
        };
        if framed {
            format!("{{ let n = {inner}; uint_len(n as u64) + n }}")
        } else {
            inner
        }
    }

    fn decode_ty(&self, ty: &Ty, cur: usize, framed: bool) -> String {
        if framed {
            let inner = self.decode_ty(ty, cur, false);
            return format!(
                "{{ let len = r.uint()? as usize; \
                 r.sub(len, |r| Ok({inner}))? }}"
            );
        }

        match ty {
            Ty::Prim(p) => prim_decode(*p),
            Ty::Struct(i) | Ty::Versioned(i) => {
                let name = self.path(*i, cur);
                format!("{name}::decode_version(r, version)?")
            }
            Ty::Enum(i) => {
                let name = self.path(*i, cur);
                format!("{name}::from_value(r.uint()?)?")
            }
            Ty::External(i) => {
                let name = self.path(*i, cur);
                format!("{name}::decode(r)?")
            }
            Ty::Array(i) => {
                let a = self.m.as_array(*i);
                let items = self.decode_items(&a.elem, cur);
                if a.newtype {
                    format!("{}({items})", self.path(*i, cur))
                } else {
                    items
                }
            }
            Ty::Record(i) => {
                let r = self.m.as_record(*i);
                let key = self.decode_ty(&r.key, cur, false);
                let value = self.decode_ty(&r.value, cur, false);
                let items = format!(
                    "{{ let n = r.uint()?; \
                     if n > MAX_ARRAY_DECODE {{ return Err(Error::ArrayTooBig(n)); }} \
                     let mut items = Vec::with_capacity((n as usize).min(r.remaining())); \
                     for _ in 0..n {{ let k = {key}; let v = {value}; items.push((k, v)); }} \
                     items }}"
                );
                format!("{}({items})", self.path(*i, cur))
            }
        }
    }

    // -- other kinds --------------------------------------------------------

    fn enum_def(&mut self, idx: usize) {
        let e = self.m.as_enum(idx);
        let name = self.m.types[idx].rust_name.clone();
        let fqn = self.m.types[idx].fqn.clone();

        self.line(1, &format!("/// `{fqn}`"));
        self.line(1, "#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
        self.line(1, &format!("pub enum {name} {{"));
        for (rust, key) in &e.variants {
            self.line(2, &format!("/// `{key}`"));
            self.line(2, &format!("{rust},"));
        }
        self.line(1, "}");
        self.line(1, "");
        self.line(1, &format!("impl {name} {{"));
        self.line(2, "/// The number this value occupies on the wire.");
        self.line(2, "pub const fn value(self) -> u64 {");
        self.line(3, "match self {");
        for (i, (rust, _)) in e.variants.iter().enumerate() {
            self.line(4, &format!("Self::{rust} => {},", i as u64 + e.offset));
        }
        self.line(3, "}");
        self.line(2, "}");
        self.line(2, "");
        self.line(
            2,
            "/// Reads a wire value, rejecting numbers outside the enum.",
        );
        self.line(2, "pub fn from_value(n: u64) -> Result<Self> {");
        self.line(3, "match n {");
        for (i, (rust, _)) in e.variants.iter().enumerate() {
            self.line(4, &format!("{} => Ok(Self::{rust}),", i as u64 + e.offset));
        }
        self.line(
            4,
            &format!("other => Err(Error::Invalid(\"unknown {fqn} value\", other)),"),
        );
        self.line(3, "}");
        self.line(2, "}");
        self.line(1, "}");
        self.line(1, "");
        self.line(1, &format!("impl Codec for {name} {{"));
        self.line(2, "fn encoded_len(&self) -> usize {");
        self.line(3, "uint_len(self.value())");
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn encode(&self, w: &mut CWriter) {");
        self.line(3, "w.uint(self.value());");
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn decode(r: &mut CReader) -> Result<Self> {");
        self.line(3, "Self::from_value(r.uint()?)");
        self.line(2, "}");
        self.line(1, "}");
        self.line(1, "");
    }

    fn array_def(&mut self, idx: usize) -> Result<()> {
        let a = self.m.as_array(idx);
        let name = self.m.types[idx].rust_name.clone();
        let fqn = self.m.types[idx].fqn.clone();
        let cur = self.m.types[idx].ns;
        let elem = self.ty_str(&a.elem, cur);
        let newtype = a.newtype;
        let elem_ty = a.elem.clone();

        self.line(1, &format!("/// `{fqn}`"));
        if !newtype {
            self.line(1, &format!("pub type {name} = Vec<{elem}>;"));
            self.line(1, "");
            return Ok(());
        }

        self.line(1, "#[derive(Debug, Clone, PartialEq)]");
        self.line(1, &format!("pub struct {name}(pub Vec<{elem}>);"));
        self.line(1, "");
        self.line(1, &format!("impl Codec for {name} {{"));
        self.line(2, "fn encoded_len(&self) -> usize {");
        self.line(3, "let version = VERSION;");
        self.line(3, &self.len_items(&elem_ty, cur, "&self.0"));
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn encode(&self, w: &mut CWriter) {");
        self.line(3, "let version = VERSION;");
        self.encode_items(&elem_ty, cur, "&self.0", 3);
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn decode(r: &mut CReader) -> Result<Self> {");
        self.line(3, "let version = VERSION;");
        self.line(
            3,
            &format!("Ok(Self({}))", self.decode_items(&elem_ty, cur)),
        );
        self.line(2, "}");
        self.line(1, "}");
        self.line(1, "");
        Ok(())
    }

    fn record_def(&mut self, idx: usize) {
        let r = self.m.as_record(idx);
        let name = self.m.types[idx].rust_name.clone();
        let fqn = self.m.types[idx].fqn.clone();
        let cur = self.m.types[idx].ns;
        let key = self.ty_str(&r.key, cur);
        let value = self.ty_str(&r.value, cur);
        let len = self.len_ty(&Ty::Record(idx), cur, "self", false);
        let decode = self.decode_ty(&Ty::Record(idx), cur, false);

        self.line(1, &format!("/// `{fqn}`"));
        self.line(1, "#[derive(Debug, Clone, PartialEq)]");
        self.line(1, &format!("pub struct {name}(pub Vec<({key}, {value})>);"));
        self.line(1, "");
        self.line(1, &format!("impl Codec for {name} {{"));
        self.line(2, "fn encoded_len(&self) -> usize {");
        self.line(3, "let version = VERSION;");
        self.line(3, &len);
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn encode(&self, w: &mut CWriter) {");
        self.line(3, "let version = VERSION;");
        self.encode_ty(&Ty::Record(idx), cur, "self", 3, false);
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn decode(r: &mut CReader) -> Result<Self> {");
        self.line(3, "let version = VERSION;");
        self.line(3, &format!("Ok({decode})"));
        self.line(2, "}");
        self.line(1, "}");
        self.line(1, "");
    }

    fn alias_def(&mut self, idx: usize) {
        let target = match &self.m.types[idx].kind {
            Kind::Alias(a) => self.ty_str(&a.target, self.m.types[idx].ns),
            _ => unreachable!(),
        };
        let fqn = self.m.types[idx].fqn.clone();
        let name = self.m.types[idx].rust_name.clone();
        self.line(1, &format!("/// `{fqn}`"));
        self.line(1, &format!("pub type {name} = {target};"));
        self.line(1, "");
    }

    fn versioned_def(&mut self, idx: usize) {
        let v = self.m.as_versioned(idx);
        let name = self.m.types[idx].rust_name.clone();
        let fqn = self.m.types[idx].fqn.clone();
        let cur = self.m.types[idx].ns;
        let framed = v.framed;
        // Only structs and other versioned types carry `*_version` methods; the
        // rest (externals, enums, arrays, records) are plain codecs.
        let defs: Vec<(u64, String, Option<String>, bool)> = v
            .defs
            .iter()
            .map(|d| {
                (
                    d.version,
                    self.ty_str(&d.ty, cur),
                    d.map.clone(),
                    matches!(d.ty, Ty::Struct(_) | Ty::Versioned(_)),
                )
            })
            .collect();

        self.line(1, &format!("/// `{fqn}`"));
        self.line(1, "#[derive(Debug, Clone, PartialEq)]");
        self.line(1, &format!("pub enum {name} {{"));
        for (version, ty, map, _) in &defs {
            match map {
                Some(map) => self.line(
                    2,
                    &format!("/// Version {version}; JS applies `{map}` to the decoded value."),
                ),
                None => self.line(2, &format!("/// Version {version}.")),
            }
            self.line(2, &format!("V{version}({ty}),"));
        }
        self.line(1, "}");
        self.line(1, "");
        self.line(1, &format!("impl {name} {{"));
        self.line(2, "/// The wire version this value writes.");
        self.line(2, "pub fn version(&self) -> u64 {");
        self.line(3, "match self {");
        for (version, _, _, _) in &defs {
            self.line(4, &format!("Self::V{version}(_) => {version},"));
        }
        self.line(3, "}");
        self.line(2, "}");
        self.line(2, "");

        self.line(
            2,
            "/// Number of bytes `encode_version` writes for this value.",
        );
        self.line(
            2,
            "pub fn encoded_len_version(&self, version: u64) -> usize {",
        );
        self.line(3, "let inner = match self {");
        for (version, _, _, version_aware) in &defs {
            let call = if *version_aware {
                "v.encoded_len_version(version)"
            } else {
                "Codec::encoded_len(v)"
            };
            self.line(4, &format!("Self::V{version}(v) => {call},"));
        }
        self.line(3, "};");
        if framed {
            self.line(
                3,
                "uint_len(self.version()) + uint_len(inner as u64) + inner",
            );
        } else {
            self.line(3, "uint_len(self.version()) + inner");
        }
        self.line(2, "}");
        self.line(2, "");

        self.line(
            2,
            "/// Writes the value, prefixed with the version it carries.",
        );
        self.line(
            2,
            "pub fn encode_version(&self, version: u64, w: &mut CWriter) {",
        );
        self.line(3, "w.uint(self.version());");
        self.line(3, "match self {");
        for (version, _, _, version_aware) in &defs {
            let call = if *version_aware {
                "v.encode_version(version, w);"
            } else {
                "Codec::encode(v, w);"
            };
            self.line(4, &format!("Self::V{version}(v) => {{"));
            if framed {
                let len = if *version_aware {
                    "v.encoded_len_version(version)"
                } else {
                    "Codec::encoded_len(v)"
                };
                self.line(5, &format!("let n = {len};"));
                self.line(5, "w.uint(n as u64);");
            }
            self.line(5, call);
            self.line(4, "}");
        }
        self.line(3, "}");
        self.line(2, "}");
        self.line(2, "");

        self.line(
            2,
            "/// Reads the version prefix and then that version's body.",
        );
        self.line(
            2,
            "pub fn decode_version(r: &mut CReader, version: u64) -> Result<Self> {",
        );
        self.line(3, "match r.uint()? {");
        let mut start = 0u64;
        for (def_version, ty, _, version_aware) in &defs {
            let arm = if start == *def_version {
                format!("{def_version}")
            } else {
                format!("{start}..={def_version}")
            };
            self.line(4, &format!("{arm} => Ok(Self::V{def_version}({{"));
            let decode = if *version_aware {
                format!("{ty}::decode_version(r, version)?")
            } else {
                format!("{ty}::decode(r)?")
            };
            if framed {
                self.line(
                    5,
                    &format!("let len = r.uint()? as usize; r.sub(len, |r| Ok({decode}))?"),
                );
            } else {
                self.line(5, &decode);
            }
            self.line(4, "})),");
            start = def_version + 1;
        }
        self.line(
            4,
            &format!("other => Err(Error::Invalid(\"unsupported {fqn} version\", other)),"),
        );
        self.line(3, "}");
        self.line(2, "}");
        self.line(1, "}");
        self.line(1, "");
        self.line(1, &format!("impl Codec for {name} {{"));
        self.line(2, "fn encoded_len(&self) -> usize {");
        self.line(3, "self.encoded_len_version(VERSION)");
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn encode(&self, w: &mut CWriter) {");
        self.line(3, "self.encode_version(VERSION, w);");
        self.line(2, "}");
        self.line(2, "");
        self.line(2, "fn decode(r: &mut CReader) -> Result<Self> {");
        self.line(3, "Self::decode_version(r, VERSION)");
        self.line(2, "}");
        self.line(1, "}");
        self.line(1, "");
    }
}

fn is_bool_ty(ty: &Ty) -> bool {
    matches!(ty, Ty::Prim(Prim::Bool))
}

/// Byte width of a fixed-size flags word.
fn flag_width(bits: u32) -> usize {
    bits.div_ceil(8).clamp(1, 8) as usize
}

fn prim_type(p: Prim) -> &'static str {
    match p {
        Prim::Uint | Prim::Uint40 | Prim::Uint48 | Prim::Uint56 | Prim::Uint64 => "u64",
        Prim::Bitwise(_) | Prim::Uint8 => "u8",
        Prim::Uint16 | Prim::Port => "u16",
        Prim::Uint24 | Prim::Uint32 => "u32",
        Prim::Int | Prim::Int40 | Prim::Int48 | Prim::Int56 | Prim::Int64 => "i64",
        Prim::Int8 => "i8",
        Prim::Int16 => "i16",
        Prim::Int24 | Prim::Int32 => "i32",
        Prim::Float32 => "f32",
        Prim::Float64 => "f64",
        Prim::String => "String",
        Prim::BigUint64 => "u64",
        Prim::BigInt64 => "i64",
        Prim::Bool => "bool",
        Prim::Buffer | Prim::Raw => "Bytes",
        Prim::OptionalBuffer => "Option<Bytes>",
        Prim::Fixed(8) => "[u8; 8]",
        Prim::Fixed(16) => "[u8; 16]",
        Prim::Fixed(24) => "[u8; 24]",
        Prim::Fixed(32) => "[u8; 32]",
        Prim::Fixed(64) => "[u8; 64]",
        Prim::Fixed(_) => "[u8; 0]",
        Prim::None => "()",
        Prim::Ip => "IpAddr",
        Prim::Ipv4 => "Ipv4Addr",
        Prim::Ipv6 => "Ipv6Addr",
        Prim::IpAddress => "SocketAddr",
        Prim::Ipv4Address => "SocketAddrV4",
        Prim::Ipv6Address => "SocketAddrV6",
    }
}

fn prim_encode(p: Prim, e: &str) -> Option<String> {
    let v = value(e);
    let text = match p {
        Prim::Uint => format!("w.uint({v});"),
        Prim::Bitwise(_) | Prim::Uint8 => format!("w.uint8({v});"),
        Prim::Uint16 => format!("w.uint16({v});"),
        Prim::Uint24 => format!("w.uint24({v});"),
        Prim::Uint32 => format!("w.uint32({v});"),
        Prim::Uint40 => format!("w.uint40({v});"),
        Prim::Uint48 => format!("w.uint48({v});"),
        Prim::Uint56 => format!("w.uint56({v});"),
        Prim::Uint64 => format!("w.uint64({v});"),
        Prim::Int => format!("w.int({v});"),
        Prim::Int8 => format!("w.int8({v});"),
        Prim::Int16 => format!("w.int16({v});"),
        Prim::Int24 => {
            format!("w.uint24((((({v}) as i64) << 1) ^ ((({v}) as i64) >> 23)) as u32);")
        }
        Prim::Int32 => format!("w.int32({v});"),
        Prim::Int40 => format!("w.uint40(((({v}) << 1) ^ (({v}) >> 39)) as u64);"),
        Prim::Int48 => format!("w.uint48(((({v}) << 1) ^ (({v}) >> 47)) as u64);"),
        Prim::Int56 => format!("w.uint56(((({v}) << 1) ^ (({v}) >> 55)) as u64);"),
        Prim::Int64 => format!("w.int64({v});"),
        Prim::Float32 => format!("w.float32({v});"),
        Prim::Float64 => format!("w.float64({v});"),
        Prim::Port => format!("w.uint16({v});"),
        Prim::String => format!("w.string({e});"),
        Prim::BigUint64 => format!("w.uint64({v});"),
        Prim::BigInt64 => format!("w.int64({v});"),
        Prim::Bool => format!("w.bool({v});"),
        Prim::Buffer => format!("w.buffer({}.as_ref());", at(e)),
        Prim::OptionalBuffer => format!("w.optional_buffer({}.as_deref());", at(e)),
        Prim::Fixed(_) | Prim::Raw => format!("w.raw({e});"),
        Prim::None => return None,
        Prim::Ip => format!("w.ip({e});"),
        Prim::Ipv4 => format!("w.ipv4({e});"),
        Prim::Ipv6 => format!("w.ipv6({e});"),
        Prim::IpAddress => format!("w.ip_address({e});"),
        Prim::Ipv4Address => format!("w.ipv4({0}.ip());\nw.uint16({0}.port());", at(e)),
        Prim::Ipv6Address => format!("w.ipv6({0}.ip());\nw.uint16({0}.port());", at(e)),
    };
    Some(text)
}

fn prim_len(p: Prim, e: &str) -> String {
    let v = value(e);
    match p {
        Prim::Uint => format!("uint_len({v})"),
        Prim::Bitwise(_) => "0".to_string(),
        Prim::Uint8 | Prim::Bool | Prim::Int8 => "1".to_string(),
        Prim::Uint16 | Prim::Port | Prim::Int16 => "2".to_string(),
        Prim::Uint24 | Prim::Int24 => "3".to_string(),
        Prim::Uint32 | Prim::Int32 | Prim::Float32 => "4".to_string(),
        Prim::Uint40 | Prim::Int40 => "5".to_string(),
        Prim::Uint48 | Prim::Int48 => "6".to_string(),
        Prim::Uint56 | Prim::Int56 => "7".to_string(),
        Prim::Uint64 | Prim::Int64 | Prim::BigUint64 | Prim::BigInt64 | Prim::Float64 => {
            "8".to_string()
        }
        Prim::Int => format!("int_len({v})"),
        Prim::String | Prim::Buffer => format!("buffer_len({}.len())", at(e)),
        Prim::OptionalBuffer => format!("optional_buffer_len({}.as_deref())", at(e)),
        Prim::Fixed(n) => n.to_string(),
        Prim::Raw => format!("{}.len()", at(e)),
        Prim::None => "0".to_string(),
        Prim::Ip => format!("1 + match {e} {{ IpAddr::V4(_) => 4, IpAddr::V6(_) => 16 }}"),
        Prim::Ipv4 => "4".to_string(),
        Prim::Ipv4Address => "6".to_string(),
        Prim::Ipv6 => "16".to_string(),
        Prim::Ipv6Address => "18".to_string(),
        Prim::IpAddress => {
            format!(
                "3 + match {}.ip() {{ IpAddr::V4(_) => 4, IpAddr::V6(_) => 16 }}",
                at(e)
            )
        }
    }
}

fn prim_decode(p: Prim) -> String {
    match p {
        Prim::Uint => "r.uint()?".to_string(),
        Prim::Bitwise(_) => "0".to_string(),
        Prim::Uint8 => "r.uint8()?".to_string(),
        Prim::Uint16 => "r.uint16()?".to_string(),
        Prim::Uint24 => "r.uint24()?".to_string(),
        Prim::Uint32 => "r.uint32()?".to_string(),
        Prim::Uint40 => "r.uint40()?".to_string(),
        Prim::Uint48 => "r.uint48()?".to_string(),
        Prim::Uint56 => "r.uint56()?".to_string(),
        Prim::Uint64 => "r.uint64()?".to_string(),
        Prim::Int => "r.int()?".to_string(),
        Prim::Int8 => "r.int8()?".to_string(),
        Prim::Int16 => "r.int16()?".to_string(),
        Prim::Int24 => "{ let n = r.uint24()? as i64; ((n >> 1) ^ -(n & 1)) as i32 }".to_string(),
        Prim::Int32 => "r.int32()?".to_string(),
        Prim::Int40 => "{ let n = r.uint40()?; ((n >> 1) as i64) ^ -((n & 1) as i64) }".to_string(),
        Prim::Int48 => "{ let n = r.uint48()?; ((n >> 1) as i64) ^ -((n & 1) as i64) }".to_string(),
        Prim::Int56 => "{ let n = r.uint56()?; ((n >> 1) as i64) ^ -((n & 1) as i64) }".to_string(),
        Prim::Int64 => "r.int64()?".to_string(),
        Prim::Float32 => "r.float32()?".to_string(),
        Prim::Float64 => "r.float64()?".to_string(),
        Prim::Port => "r.uint16()?".to_string(),
        Prim::String => "r.string()?".to_string(),
        Prim::BigUint64 => "r.uint64()?".to_string(),
        Prim::BigInt64 => "r.int64()?".to_string(),
        Prim::Bool => "r.bool()?".to_string(),
        Prim::Buffer => "r.buffer()?".to_string(),
        Prim::OptionalBuffer => "r.optional_buffer()?".to_string(),
        Prim::Fixed(8) => "r.fixed::<8>()?".to_string(),
        Prim::Fixed(16) => "r.fixed::<16>()?".to_string(),
        Prim::Fixed(24) => "r.fixed::<24>()?".to_string(),
        Prim::Fixed(32) => "r.fixed::<32>()?".to_string(),
        Prim::Fixed(64) => "r.fixed::<64>()?".to_string(),
        Prim::Fixed(n) => format!("r.fixed::<{n}>()?"),
        Prim::Raw => "r.raw()".to_string(),
        Prim::None => "()".to_string(),
        Prim::Ip => "r.ip()?".to_string(),
        Prim::Ipv4 => "r.ipv4()?".to_string(),
        Prim::Ipv6 => "r.ipv6()?".to_string(),
        Prim::IpAddress => "r.ip_address()?".to_string(),
        Prim::Ipv4Address => "SocketAddrV4::new(r.ipv4()?, r.uint16()?)".to_string(),
        Prim::Ipv6Address => "SocketAddrV6::new(r.ipv6()?, r.uint16()?, 0, 0)".to_string(),
    }
}

fn constant_literal(value: &serde_json::Value) -> String {
    if value.is_null() {
        return "None".to_string();
    }
    if let Some(b) = value.as_bool() {
        return b.to_string();
    }
    if let Some(i) = value.as_i64() {
        return i.to_string();
    }
    format!("{:?}.to_string()", value.as_str().unwrap_or_default())
}
